ze;            // whole-photo previews use the camera's shape\n    for(let i = 0; i < count; i++) shots.push(sampleShot(cw, ch, count > 1 ? i + 1 : 0));\n    return shots;\n  }\n\n  function renderSetupPreview(){\n    if(!setupPreviewCanvas) return;\n    const needed = shotsNeeded(currentLayout);\n    const haveRealShots = shotCanvases.length === needed && shotCanvases.every(Boolean);\n    const shotsToUse = haveRealShots ? shotCanvases : buildPlaceholderShots(400, needed);\n    accentUsed = false;\n    composeCanvas(currentLayout, setupPreviewCanvas, shotsToUse);\n    previewUsesAccent = accentUsed;\n    if(typeof refreshAccentHelp === 'function') refreshAccentHelp();\n    if(typeof drawFrameOverlays === 'function') drawFrameOverlays();\n    if(typeof drawDecorSelection === 'function') drawDecorSelection();\n    if(typeof scheduleWelcomeRender === 'function') scheduleWelcomeRender();\n    afterSetupPreview();\n  }\n\n\n  // ---- Download / Share ----\n\n  shareBtn.addEventListener('click', () => {\n    previewCanvas.toBlob(async (blob) => {\n      if(!blob) return;\n      const file = new File([blob], 'photo-booth.png', { type: 'image/png' });\n      if(navigator.canShare && navigator.canShare({ files: [file] })){\n        try{\n          await navigator.share({ files: [file], title: 'My Photo Booth', text: 'Check out my photo booth pic!' });\n        }catch(err){\n          // user cancelled the share sheet, nothing to do\n        }\n      }else{\n        const link = document.createElement('a');\n        link.download = 'photo-booth-' + Date.now() + '.png';\n        link.href = previewCanvas.toDataURL('image/png');\n        link.click();\n        showToast('Sharing isn\\'t supported here, so the photo was saved instead.', 4200);\n      }\n    }, 'image/png');\n  });\n\n  // ---- Printing ----\n  // Only shown when this rental (or the trial) allows printing — the lock\n  // screen passes { enabled, sizes } in window.__PB.print, and the 5-minute\n  // license check